(()=>{
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fillings={A1:[['韭菜鸡蛋','Poireau et œuf']],A2:[['猪肉白菜','Porc et chou'],['鲜肉','Porc'],['韭菜猪肉','Porc et poireau']],A3:[['红油牛肉包','Bao au bœuf pimenté'],['牛肉鲜肉包','Bao au bœuf frais']]},standard=[['韭菜鸡蛋','Poireau et œuf'],['鲜肉','Porc'],['牛肉','Bœuf']],styles={包子:[['清蒸','Vapeur'],['煎包','Poêlé']],饺子:[['水煮','À l’eau'],['清蒸','Vapeur'],['煎饺','Poêlés']]};
 const key=item=>JSON.stringify((item.components||[]).map(c=>[c.code,c.filling||'',c.style||'']));
 function valid(item){const p=BaoCatalog.get(item.code),r=p?.bundle,c=item.components;return !!(p?.active&&r&&Array.isArray(c)&&c.length===r.mainCount+r.drinkCount&&c.every((v,i)=>BaoCatalog.get(v.code)?.active&&(i<r.mainCount?r.mains:r.drinks).includes(v.code)&&v.qty===1))}
 function lines(item){return (item.components||[]).map(c=>`${c.fr||c.dish}${c.category==='饺子'?' · 9 pièces / 9个':''}${c.filling?' · '+(c.fillingFr||c.filling)+' · '+(c.styleFr||c.style):''} × ${c.qty*Number(item.qty||1)} / ${c.dish}${c.filling?' · '+c.filling+' · '+c.style:''}`).join('\n')}
 function html(item){return item.components?'<span class="bundle-components"><b>Menu · 套餐组成</b>'+lines(item).split('\n').map(line=>'<span>'+esc(line)+'</span>').join('')+'</span>':''}
 function open(product,commit,existing){if(!product?.bundle)return false;
 const rule=JSON.parse(JSON.stringify(product.bundle)),components=existing?.components?JSON.parse(JSON.stringify(existing.components)):Array(rule.mainCount+rule.drinkCount).fill(null);let step=existing?components.length:0,quantity=existing?.qty||1;
 const dialog=document.createElement('dialog');dialog.className='variant-dialog bundle-dialog';dialog.setAttribute('aria-label','Composer le menu · 选择套餐');dialog.innerHTML='<div class="variant-body"><button class="variant-close" type="button" aria-label="Fermer · 关闭">×</button><h2></h2><p class="bundle-progress"></p><div class="bundle-stage"></div><p class="bundle-error" role="status"></p><div class="bundle-navigation"><button type="button" class="button" data-back>Retour · 上一步</button><button type="button" class="button primary" data-next>Suivant · 下一步</button></div></div>';
 const area=dialog.querySelector('.bundle-stage'),message=dialog.querySelector('.bundle-error'),next=dialog.querySelector('[data-next]');dialog.querySelector('h2').textContent=product.fr+' · '+product.dish;
 function complete(){return components.every((c,i)=>c&&BaoCatalog.get(c.code)?.active&&(i>=rule.mainCount||c.filling&&c.style))}
 function options(label,choices,selected,choose){const group=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=label;group.append(legend);for(const c of choices){const b=document.createElement('button');b.type='button';b.className='variant-option';b.textContent=c.label;b.disabled=c.disabled||false;b.dataset.value=c.value;b.setAttribute('aria-pressed',String(selected===c.value));b.onclick=()=>{choose(c.value);render()};group.append(b)}area.append(group)}
 function render(){message.textContent='';area.replaceChildren();dialog.querySelector('[data-back]').disabled=step===0;const limit=components.length;
 dialog.querySelector('.bundle-progress').textContent=step<rule.mainCount?`1 · Plat ${step+1}/${rule.mainCount} / 选择第${step+1}份主食`:step<limit?`2 · Boisson ${step-rule.mainCount+1}/${rule.drinkCount} / 选择饮品`:'3 · Vérifier le menu / 核对套餐';
 if(step<limit){const main=step<rule.mainCount,allowed=main?rule.mains:rule.drinks,current=components[step];options(main?'Produit · 主食':'Boisson · 饮品',allowed.map(code=>{const p=BaoCatalog.get(code);return {value:code,label:p?(p.fr+' / '+p.dish+(p.active?'':' · Épuisé / 售罄')):code+' · Indisponible',disabled:!p?.active}}),current?.code,code=>{const p=BaoCatalog.get(code);components[step]={code:p.code,dish:p.dish,fr:p.fr,category:p.category,qty:1}});
 const c=components[step];if(main&&c){options('Garniture · 馅料',(fillings[c.code]||standard).map(([zh,fr])=>({value:zh,label:fr+' / '+zh})),c.filling,v=>{const f=(fillings[c.code]||standard).find(x=>x[0]===v);Object.assign(c,{filling:f[0],fillingFr:f[1]})});options('Cuisson · 做法',styles[c.category].map(([zh,fr])=>({value:zh,label:fr+' / '+zh})),c.style,v=>{const s=styles[c.category].find(x=>x[0]===v);Object.assign(c,{style:s[0],styleFr:s[1]})})}
 next.disabled=!(c&&BaoCatalog.get(c.code)?.active&&(!main||c.filling&&c.style));next.textContent=existing?'Vérifier le menu · 核对套餐':'Suivant · 下一步';
 }else{area.innerHTML=html({components,qty:quantity})+'<label>Nombre de menus · 套餐数量 <input class="bundle-qty" type="number" min="1" max="999" step="1"></label><p class="bundle-price"></p><small>Prix du menu uniquement, sans double facturation. / 仅收套餐价，组成商品不重复计费。</small>';if(existing){const links=document.createElement('div');links.className='bundle-edit-links';components.forEach((c,i)=>{const button=document.createElement('button');button.type='button';button.className='button';button.textContent=(i<rule.mainCount?'Modifier le plat / 修改主食 ':'Changer la boisson / 更换饮品 ')+(i<rule.mainCount?i+1:i-rule.mainCount+1);button.onclick=()=>{step=i;render()};links.append(button)});area.prepend(links)}const input=area.querySelector('input');input.value=quantity;const update=()=>{quantity=Number(input.value);next.disabled=!complete()||!Number.isInteger(quantity)||quantity<1||quantity>999;area.querySelector('.bundle-price').textContent=(quantity*product.price).toFixed(2).replace('.',',')+' €'};input.oninput=update;update();next.textContent=existing?'Enregistrer · 保存修改':'Ajouter au panier · 加入购物车'}
 }
 dialog.querySelector('[data-back]').onclick=()=>{step--;render()};next.onclick=()=>{if(step<components.length){step=existing?components.length:step+1;render();return}try{const latest=BaoCatalog.get(product.code);if(!latest?.active)throw Error('Menu indisponible / 套餐暂不可售');if(JSON.stringify(latest.bundle)!==JSON.stringify(rule))throw Error('Menu modifié. Fermez et choisissez à nouveau. / 套餐组成已调整，请关闭后重新选择');if(latest.price!==product.price){product={...latest};render();throw Error('Prix actualisé, vérifiez puis confirmez. / 价格已更新，请核对后再确认')}const item={...latest,components,qty:quantity};if(!valid(item))throw Error('Choix indisponible, vérifiez le menu. / 套餐商品已售罄，请重新选择');commit(item);dialog.close()}catch(e){message.textContent=e.message}};
 dialog.querySelector('.variant-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);render();dialog.showModal();return true;
 }
 function photo(p){if(!p.bundle||BaoCatalog.customImage(p))return '';const main=BaoCatalog.get(p.bundle.mains[0]),drink=BaoCatalog.get(p.bundle.drinks[0]);return '<span class="bundle-photo"><img class="bundle-main-image" src="'+esc(BaoCatalog.imageFor(main))+'" alt=""><span>＋</span><img src="'+esc(BaoCatalog.imageFor(drink))+'" alt=""><small>'+p.bundle.mainCount+(p.bundle.mainCategory==='包子'?' bao':' × 9 pièces')+' + '+p.bundle.drinkCount+' boisson(s)</small></span>'}
 window.BaoBundles={open,key,valid,html,lines,photo};
})();
